{
  "judgments": [
    {
      "proposal_id": "P0000",
      "source_refs": ["F000", "F025:F026"],
      "rationale": "Paragraph (a) in F000 conditions the mandatory railroad crossing stop on the exceptions provided in paragraph (b). Paragraph (b)(1) in F025:F026 provides that a stop need not be made at streetcar crossings or industrial switching tracks within a business district. Setting relation to exception and linking qualifies to C0000 accurately converts this textual caveat into an explicit qualification edge while preserving all other properties.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0001",
      "source_refs": ["F000", "F025", "F027"],
      "rationale": "Paragraph (a) in F000 explicitly subjects the stopping requirement to the exceptions in paragraph (b). Paragraph (b)(2) in F025 and F027 establishes an exemption when a police officer or crossing flagman directs traffic to proceed. Updating relation to exception and targeting C0000 in qualifies establishes the correct dependency between the baseline stop duty and its exception.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0002",
      "source_refs": ["F000", "F025", "F028"],
      "rationale": "The stopping duty in F000 is expressly conditioned by paragraph (b), and paragraph (b)(3) in F025 and F028 exempts crossings controlled by a functioning green highway traffic signal permitting passage under local law. Adding an exception relation that qualifies baseline requirement C0000 correctly operationalizes this exception edge without altering any other verified fields.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0003",
      "source_refs": ["F000", "F025", "F029"],
      "rationale": "Under F000, the stopping requirement applies except as provided in paragraph (b). Paragraph (b)(4) in F025 and F029 provides that a stop need not be made at marked abandoned railroad grade crossings. Setting relation to exception and qualifies to C0000 properly reflects the statutory caveat qualifying the baseline duty.",
      "verdict": "supported"
    },
    {
      "proposal_id": "P0004",
      "source_refs": ["F000", "F025", "F030"],
      "rationale": "Paragraph (a) in F000 introduces the stopping requirement subject to the exceptions in paragraph (b). Paragraph (b)(5) in F025 and F030 establishes that a stop need not be made at industrial or spur line grade crossings marked 'Exempt'. Linking C0013 as an exception qualifying C0000 accurately represents this relationship.",
      "verdict": "supported"
    }
  ]
}
